CREATE OR REPLACE FUNCTION public.trackdash_notify_marketplace_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' and new.status='pending_confirmation' then
    perform public.trackdash_emit_notification(new.buyer_id,'marketplace_sale_confirmation_due',null,null,'/messages?conversation='||new.conversation_id::text,'marketplace_sale',new.id,'sale:'||new.id::text||':buyer-confirmation',jsonb_build_object('conversationId',new.conversation_id,'saleId',new.id,'itemPrice',new.item_price,'shippingPrice',new.shipping_price,'currency',new.currency),now());
  elsif tg_op='UPDATE' and new.status='confirmed' and old.status is distinct from new.status then
    perform public.trackdash_emit_notification(new.seller_id,'marketplace_sale_confirmed',null,null,'/messages?conversation='||new.conversation_id::text,'marketplace_sale',new.id,'sale:'||new.id::text||':confirmed',jsonb_build_object('conversationId',new.conversation_id,'saleId',new.id,'itemPrice',new.item_price,'shippingPrice',new.shipping_price,'currency',new.currency),now());
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trackdash_queue_recompute_from_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE')
     and old.release_id is not null
     and old.attribution_status in ('release_exact','release_matched')
     and old.market_average_eur is not null
  then
    perform public.trackdash_enqueue_market_recompute(old.release_id, old.condition);
  end if;

  if tg_op in ('INSERT','UPDATE')
     and new.release_id is not null
     and new.attribution_status in ('release_exact','release_matched')
     and new.market_average_eur is not null
  then
    perform public.trackdash_enqueue_market_recompute(new.release_id, new.condition);
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.trackdash_queue_recompute_from_marketplace_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE')
     and old.status = 'confirmed'
     and old.item_price_eur is not null
     and old.item_price_eur > 0
  then
    perform public.trackdash_enqueue_market_recompute(
      old.release_id,
      public.trackdash_marketplace_sale_condition(old.condition)
    );
  end if;

  if tg_op in ('INSERT','UPDATE')
     and new.status = 'confirmed'
     and new.item_price_eur is not null
     and new.item_price_eur > 0
  then
    perform public.trackdash_enqueue_market_recompute(
      new.release_id,
      public.trackdash_marketplace_sale_condition(new.condition)
    );
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.trackdash_queue_recompute_from_price_point()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  old_relevant boolean := false;
  new_relevant boolean := false;
begin
  if tg_op in ('UPDATE','DELETE') then
    old_relevant :=
      old.status = 'active'
      and old.valuation_eligible
      and old.observation_type in ('sold_confirmed','auction_awarded','marketplace_sold')
      and coalesce(old.market_price_eur, old.normalized_price_eur) is not null;
    if old_relevant then
      perform public.trackdash_enqueue_market_recompute(old.release_id, old.condition);
    end if;
  end if;

  if tg_op in ('INSERT','UPDATE') then
    new_relevant :=
      new.status = 'active'
      and new.valuation_eligible
      and new.observation_type in ('sold_confirmed','auction_awarded','marketplace_sold')
      and coalesce(new.market_price_eur, new.normalized_price_eur) is not null;
    if new_relevant then
      perform public.trackdash_enqueue_market_recompute(new.release_id, new.condition);
    end if;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.market_candidate_release_revalidation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.resolved_release_id is distinct from old.resolved_release_id then
    new.needs_revalidation := true;
    update public.price_points
    set needs_revalidation = true, valuation_eligible = false, updated_at = now()
    where candidate_id = old.id;
  end if;
  return new;
end;
$function$
